import { animateIosApp } from '../phone-v2/app-motion.mjs';
import { installSerialMotion } from '../ui/serial-motion.mjs';
import { patchHtml } from '../phone-v2/dom-patch.mjs';
import { WorkshopServiceForm } from './workshop-service-model.mjs';
import { WORKSHOP_SERVICE_STYLE } from './workshop-service-style.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={vip:'<path d="m12 2 3 6.5 7 1-5 5 1.2 7.1-6.2-3.3-6.2 3.3L7 14.5l-5-5 7-1z" fill="currentColor"/>',energy:'<path d="M14 2 5 14h6l-1 8 9-12h-6z" fill="currentColor"/>',benefit:'<rect x="4" y="9" width="16" height="12" rx="2" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M3 9h18M12 9v12M12 9C5 9 5 3 8 3c2 0 4 6 4 6s2-6 4-6c3 0 3 6-4 6Z" fill="none" stroke="currentColor" stroke-width="1.8"/>',check:'<path d="m4 12 5 5L20 6" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]}</svg>`;
const title={vip:'VIP 升级',energy:'能量补充',benefit:'MC 上限福利'};
export async function mountWorkshopServiceWindow(container,{service,mode='vip',readResources,resolveFile=x=>x,twinsHead='scene-presence/heads/hacker-twins-joint-v1.png',isWritable=()=>true,onClose=()=>{}}){
 const doc=container.ownerDocument,motion=installSerialMotion(doc),root=doc.createElement('section');root.className='vip-service-window';root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');container.append(root);const style=doc.createElement('style');style.textContent=WORKSHOP_SERVICE_STYLE+`.workshop-appstage{flex:1;min-height:0;position:relative;overflow:hidden}.workshop-appcontent{position:absolute;inset:0;display:flex;flex-direction:column;overflow:hidden}.workshop-home{height:100%;padding:40px 28px;background:radial-gradient(ellipse at 20% 20%,#b2bff9,transparent 60%),linear-gradient(140deg,#818fdb,#e2d5f5);color:#fff}.workshop-home button{display:flex;flex-direction:column;align-items:center;gap:9px;background:none;color:inherit;font-size:12px}.workshop-home img{width:64px;height:64px;padding:5px;background:#fff;border-radius:17px;box-shadow:0 5px 12px #27326533}.workshop-home-indicator{border:0;cursor:pointer;flex:none}`;root.append(style);const body=doc.createElement('div');root.append(body);
 const form=new WorkshopServiceForm({service,mode,readResources,isWritable,onChange:render});let destroyed=false,homeVisible=true;
 function navigation(){return`<nav class="vip-service-tabbar" role="tablist" aria-label="应用服务类别">${Object.keys(title).map(mode=>`<button data-workshop-mode="${mode}" role="tab" aria-selected="${form.mode===mode}" ${form.busy?'disabled':''}>${icon(mode)}<span>${mode==='benefit'?'上限福利':title[mode]}</span></button>`).join('')}</nav>`;}
 function choice(label,attribute,value,selected,disabled=false,detail=''){return`<button class="vip-service-choice" ${attribute}="${esc(value)}" aria-pressed="${selected}" ${disabled?'disabled':''}>${esc(label)}${detail?`<small>${esc(detail)}</small>`:''}</button>`;}
 function fields(){
  if(form.mode==='vip'){const ranks=form.item?.targetRanks??[],current=Number(form.balances.vipRank??0);return `<h2 class="vip-service-section-title">目标等级</h2><div class="vip-service-list">${ranks.map(option=>{const rank=Number(option?.targetRank??option?.rank??option);return `<button class="vip-service-option" data-target-rank="${rank}" aria-pressed="${rank===Number(form.options.targetRank)}" ${form.busy||rank<=current?'disabled':''}><span>VIP ${rank}</span><span>${icon('check')}</span></button>`;}).join('')||'<div class="vip-service-empty">已达到最高 VIP 等级</div>'}</div><p class="vip-service-description">可直接选择更高等级。</p>`;}
  if(form.mode==='energy')return`<h2 class="vip-service-section-title">补充额度</h2><div class="vip-service-choice-grid">${(form.item?.amountOptions??[]).map(amount=>choice(Number(amount).toLocaleString(),'data-energy-amount',amount,Number(amount)===Number(form.options.amount),form.busy,'MC')).join('')}</div><label class="vip-service-input"><span>自选额度</span><input id="workshop-energy-amount" data-energy-custom type="number" min="1" step="1" inputmode="numeric" aria-label="自选能量补充额度" value="${esc(form.options.amount??'')}" ${form.busy?'disabled':''}><span>MC</span></label>`;
  const tiers=form.item?.tiers??[],tier=tiers.find(item=>item.id===form.options.tier),selected=new Set(form.options.characterIds??[]);
  return`<h2 class="vip-service-section-title">福利档位</h2><div class="vip-service-choice-grid vip-service-benefit-grid">${tiers.map(item=>choice(item.requiredCharacters+'人 · '+item.minPermanent+'项','data-benefit-tier',item.id,item.id===form.options.tier,form.busy,item.claimed?'已领取':'+ '+Number(item.increase).toLocaleString()+' 上限')).join('')}</div><p class="vip-service-benefit-copy">${tier?`选择 ${tier.requiredCharacters} 位槽内人物，每位至少 ${tier.minPermanent} 项永久催眠。`:''}<br>每档免费领取一次，人物与催眠记录均保留。</p><h2 class="vip-service-section-title">提供人物</h2><div class="vip-service-list">${form.candidates.length?form.candidates.map(person=>`<button class="vip-service-person" data-benefit-person="${esc(person.id)}" aria-pressed="${selected.has(person.id)}" ${form.busy||tier?.claimed?'disabled':''}><span>${icon('check')}</span><strong>${esc(person.name)}</strong><small>${Number(person.permanentCount)} 项永久催眠</small></button>`).join(''):'<div class="vip-service-empty">当前人物卡槽为空</div>'}</div>`;
 }
 function paintBody(markup){const current=body.querySelector('.workshop-appcontent:not([data-app-transition-layer])');if(!current){patchHtml(body,markup);return;}const template=doc.createElement('template');template.innerHTML=markup;patchHtml(current,template.content.querySelector('.workshop-appcontent').innerHTML);body.querySelector('time').textContent=template.content.querySelector('time').textContent;}
 function render(){if(destroyed)return;const {balances,quote}=form,benefit=form.mode==='benefit',claimed=benefit&&(quote?.claimed||form.item?.tiers?.find(item=>item.id===form.options.tier)?.claimed),quoteLabel=form.mode==='vip'?'升级至 VIP '+(form.options.targetRank??'—'):form.mode==='energy'?'补充 '+Number(form.options.amount??0).toLocaleString()+' MC':'免费福利',fee=benefit?(claimed?'已领取':'+ 1,500 MC 上限'):quote?'¥'+Number(quote.price.amount).toLocaleString():'—';root.setAttribute('aria-label','双胞胎工作室 · 应用服务');body.className='workshop-surface';paintBody(`<div class="workshop-device-status" aria-label="服务手机状态栏"><time>${new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}</time><span class="workshop-camera" aria-hidden="true"><i></i></span><span class="workshop-device-indicators" aria-hidden="true"><svg viewBox="0 0 20 14"><path d="M1 10h3v4H1zm5-3h3v7H6zm5-3h3v10h-3zm5-3h3v13h-3z"/></svg><svg viewBox="0 0 20 15"><path d="M1 5Q10-3 19 5M4 8q6-6 12 0M7 11q3-3 6 0" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/><circle cx="10" cy="14" r="1.3"/></svg><svg viewBox="0 0 27 14"><rect x="1" y="1" width="22" height="12" rx="3" fill="none" stroke="currentColor"/><rect x="3" y="3" width="18" height="8" rx="1.4"/><path d="M25 5v4" stroke="currentColor" stroke-width="2"/></svg></span></div><div class="workshop-appstage"><main class="workshop-appcontent">${homeVisible?`<div class="workshop-home"><button data-workshop-open aria-label="打开应用服务"><img src="${esc(resolveFile(twinsHead))}" alt=""><span>应用服务</span></button></div>`:`<header class="vip-service-header"><div class="vip-service-heading"><img src="${esc(resolveFile(twinsHead))}" alt="双胞胎服务应用"><strong>应用服务</strong></div><button class="vip-service-close" data-workshop-close aria-label="关闭应用服务"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></button></header><div class="vip-service-main"><div class="vip-service-account" aria-label="账户概况"><span><small>零花钱</small><strong>¥${Number(balances.money??0).toLocaleString()}</strong></span><span><small>MC / 上限</small><strong>${Number(balances.energy??0).toLocaleString()} / ${Number(balances.energyCap??0).toLocaleString()}</strong></span><span><small>订阅</small><strong>VIP ${Number(balances.vipRank??0)}</strong></span></div><div class="vip-service-content" role="tabpanel" aria-label="${title[form.mode]}">${fields()}</div><footer class="vip-service-footer"><div class="vip-service-quote"><div><small>${esc(quoteLabel)}</small><strong>${esc(fee)}</strong></div><button class="vip-service-submit" data-workshop-submit ${form.canSubmit?'':'disabled'}>${claimed?'已领取':form.busy?'正在加入…':'加入日程'}</button></div><p class="vip-service-notice" data-error="${Boolean(form.error||quote?.reason)}" role="status">${esc(form.error||quote?.reason||form.notice||'送出日程并确认结果后生效。')}</p></footer></div>${navigation()}`}</main></div><button class="workshop-home-indicator" data-workshop-home aria-label="返回服务手机主屏幕"><i></i></button>`);}
 async function navigateHome(next){if(destroyed||homeVisible===next)return;const content=body.querySelector('.workshop-appcontent:not([data-app-transition-layer])'),origin=body.querySelector('[data-workshop-open] img')?.getBoundingClientRect();await animateIosApp(content,{kind:next?'close':'open',origin:next?()=>body.querySelector('[data-workshop-open] img')?.getBoundingClientRect():origin,render(){homeVisible=next;render();}});}
 async function click(event){const button=event.target.closest('button');if(!button||button.disabled)return;if(button.hasAttribute('data-workshop-home')){await motion.run(()=>navigateHome(true));return;}if(button.hasAttribute('data-workshop-open')){await motion.run(()=>navigateHome(false));return;}if(button.hasAttribute('data-workshop-close')){onClose();return;}if(button.hasAttribute('data-workshop-submit')){await form.submit();return;}if(button.hasAttribute('data-workshop-mode')){if(form.mode!==button.dataset.workshopMode)await motion.run(()=>animateIosApp(body.querySelector('.workshop-appcontent:not([data-app-transition-layer])'),{kind:'push',render:()=>form.switchMode(button.dataset.workshopMode)}));}else if(button.hasAttribute('data-target-rank'))await form.choose({targetRank:Number(button.dataset.targetRank)});else if(button.hasAttribute('data-energy-amount'))await form.choose({amount:Number(button.dataset.energyAmount)});else if(button.hasAttribute('data-benefit-tier'))await form.choose({tier:button.dataset.benefitTier,characterIds:[]});else if(button.hasAttribute('data-benefit-person')){const ids=[...(form.options.characterIds??[])],id=button.dataset.benefitPerson,index=ids.indexOf(id),tier=form.item?.tiers?.find(item=>item.id===form.options.tier);if(index>=0)ids.splice(index,1);else{if(ids.length>=Number(tier?.requiredCharacters??1))ids.shift();ids.push(id);}await form.choose({...form.options,characterIds:ids});}}
 function input(event){if(event.target.hasAttribute('data-energy-custom'))void form.choose({amount:event.target.value===''?'':Number(event.target.value)});}
 function key(event){if(event.key==='Escape'){event.stopPropagation();onClose();}}
 root.addEventListener('click',click);root.addEventListener('input',input);root.addEventListener('keydown',key);render();try{await form.refresh();}catch(error){form.error=error.message;render();}
 return{root,form,openApp:()=>navigateHome(false),closeApp:()=>navigateHome(true),refresh:()=>form.refresh(),destroy(){destroyed=true;form.destroy();root.removeEventListener('click',click);root.removeEventListener('input',input);root.removeEventListener('keydown',key);root.remove();}};
}
